        int leftBits = Float.floatToIntBits(left);
        int rightBits = Float.floatToIntBits(right);
        int leftEncoded = leftBits ^ (leftBits >> 31) & 0x7fffffff;
        int rightEncoded = rightBits ^ (rightBits >> 31) & 0x7fffffff;
        int leftViaXy = XYEncodingUtils.encode(left);
        int rightViaXy = XYEncodingUtils.encode(right);
        if (leftEncoded == leftViaXy && rightEncoded == rightViaXy) {
          leftSortable[dim] = leftEncoded;
          rightSortable[dim] = rightEncoded;
          int offset = dim * 4;
