    }
    this.minX = checkVal(minX);
    this.maxX = checkVal(maxX);
    this.minY = checkVal(minY);
    this.maxY = checkVal(maxY);
  }

  @Override
  protected Component2D toComponent2D() {
    return Rectangle2D.create(this);
  }

  @Override
